type agreementMappedCodeP2Reading struct {
	Cut                                                                   agreementRemovedCommentDiagnosticReading
	Native                                                                agreementNativeOwnerSource
	Check                                                                 agreementNativeCheckSource
	Tree                                                                  agreementNativeProseAddressTree
	Sites                                                                 []agreementNativeCodePayloadSite
	HTMLSites                                                             []agreementNativeHTMLAddressSite
	Projected, Neutral                                                    string
	Positions, NeutralPositions                                           []int
	Plain, Page, ProjectedPlain, ProjectedPage, NeutralPlain, NeutralPage []agreementNativeCodeWindow
	Valid                                                                 bool
}

// Every code window retains its complete literal payload. Removing declared
// comments and reserved bytes keeps a map to the whole authored source.
func agreementMappedCodeP2Read(body string) agreementMappedCodeP2Reading {
	r := agreementMappedCodeP2Reading{Cut: agreementCommentCutP0Reading(body)}
	if !utf8.ValidString(body) {
		return r
	}
	r.Projected, r.Positions = r.Cut.Projected, slices.Clone(r.Cut.Positions)
	if len(r.Cut.Check.Comments) == 0 {
		r.Projected = body
		r.Positions = make([]int, len(body))
		for i := range r.Positions {
			r.Positions[i] = i
		}
	} else if !r.Cut.Valid {
		return r
	}
	if len(r.Projected) != len(r.Positions) {
		return r
	}
	for i, at := range r.Positions {
		if at < 0 || at >= len(body) || body[at] != r.Projected[i] || (i > 0 && at <= r.Positions[i-1]) {
			return r
		}
	}
	var neutral strings.Builder
	for at, c := range r.Projected {
		if strings.ContainsRune(agreementNeutralHeadingRunes, c) {
			continue
		}
		size := utf8.RuneLen(c)
		if size < 1 || at+size > len(r.Projected) {
			return r
		}
		neutral.WriteString(r.Projected[at : at+size])
		r.NeutralPositions = append(r.NeutralPositions, r.Positions[at:at+size]...)
	}
	r.Neutral = neutral.String()
	for i, at := range r.NeutralPositions {
		if at < 0 || at >= len(body) || body[at] != r.Neutral[i] || (i > 0 && at <= r.NeutralPositions[i-1]) {
			return r
		}
	}
	r.Native = agreementNativeOwnerReading(body)
	r.Check = agreementNativeCheckReading(body, r.Native)
	r.Tree = agreementNativeProseAddressTreeReading(body, nil)
	r.Sites = agreementNativeCodePayloadSites(body)
	r.HTMLSites = agreementNativeHTMLAddressSites(body)
	if !r.Tree.Valid || !slices.Equal(r.Check.Targets, judge.LinkTargets(body)) {
		return r
	}
	var valid [6]bool
	r.Plain, valid[0] = agreementNativeCodeWindows(body, agreementFootnoteGrammar)
	r.Page, valid[1] = agreementNativeCodeWindows(body, agreementExclusiveCodeGrammar)
	r.ProjectedPlain, valid[2] = agreementNativeCodeWindows(r.Projected, agreementFootnoteGrammar)
	r.ProjectedPage, valid[3] = agreementNativeCodeWindows(r.Projected, agreementExclusiveCodeGrammar)
	r.NeutralPlain, valid[4] = agreementNativeCodeWindows(r.Neutral, agreementFootnoteGrammar)
	r.NeutralPage, valid[5] = agreementNativeCodeWindows(r.Neutral, agreementExclusiveCodeGrammar)
	for _, ok := range valid {
		if !ok {
			return r
		}
	}
	r.Valid = true
	return r
}

type agreementMappedCodeP2Field struct {
	Window                                                         int
	OriginalField, ProjectedField, OriginalTarget, ProjectedTarget graph.Span
	Old, New                                                       string
}

func agreementMappedCodeP2Physical(body string, f *agreementFailure, r *agreementMappedCodeP2Reading, parts [][]agreementCodePart) (string, []agreementMappedCodeP2Field, bool) {
	if f == nil || r == nil || !r.Valid || f.Property != "P2" || f.Identity != "wikilink-in-code" || f.Direction != "page-in-code" || f.Tuple.SourceRole != "" || f.Tuple.Section != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Target == "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Multiplicity <= 0 || strings.Contains(body, "q") || len(r.Neutral) != len(r.NeutralPositions) || len(parts) != len(r.NeutralPage) {
		return "", nil, false
	}
	for i, at := range r.NeutralPositions {
		if at < 0 || at >= len(body) || body[at] != r.Neutral[i] || (i > 0 && at <= r.NeutralPositions[i-1]) {
			return "", nil, false
		}
	}
	budget := make(map[agreementCitation]int)
	private := []byte(body)
	seenTargets := make(map[int]bool)
	var fields []agreementMappedCodeP2Field
	replacement := strings.Repeat("q", len(f.Tuple.Target))
	for wi, window := range r.NeutralPage {
		owned, ok := agreementMatchCodeWindow(window.Text, parts[wi])
		if !ok {
			return "", nil, false
		}
		for tuple, n := range owned {
			budget[tuple] += n
		}
		if owned[f.Tuple] == 0 {
			continue
		}
		if window.Kind != "CodeSpan" || window.Span.Start < 0 || window.Span.Stop > len(r.Neutral) || window.Span.Start >= window.Span.Stop {
			return "", nil, false
		}
		count := 0
		for offset := window.Span.Start; offset < window.Span.Stop; {
			rel := strings.Index(r.Neutral[offset:window.Span.Stop], "[[")
			if rel < 0 {
				break
			}
			open := offset + rel
			closeAt := strings.Index(r.Neutral[open+2:window.Span.Stop], "]]")
			if closeAt < 0 {
				return "", nil, false
			}
			end := open + 2 + closeAt + 2
			offset = end
			inner := r.Neutral[open+2 : end-2]
			link, valid := graph.ParseWikilink(inner)
			if !valid || graph.EscapedWikilinkAt(r.Neutral, open) || (open > 0 && r.Neutral[open-1] == '!') || link.Block != "" || link.Target != f.Tuple.Target || link.Heading != f.Tuple.Section {
				continue
			}
			start := open + 2 + strings.Index(inner, link.Target)
			stop := start + len(link.Target)
			if start < open+2 || stop > end-2 || r.Neutral[start:stop] != link.Target {
				return "", nil, false
			}
			originalOpen := r.NeutralPositions[open]
			for i := open; i < end; i++ {
				if r.NeutralPositions[i] != originalOpen+i-open {
					return "", nil, false
				}
			}
			originalEnd := originalOpen + end - open
			if body[originalOpen:originalEnd] != r.Neutral[open:end] {
				return "", nil, false
			}
			originalStart, originalStop := r.NeutralPositions[start], r.NeutralPositions[stop-1]+1
			if seenTargets[originalStart] || body[originalStart:originalStop] != link.Target {
				return "", nil, false
			}
			seenTargets[originalStart] = true
			copy(private[originalStart:originalStop], replacement)
			fields = append(fields, agreementMappedCodeP2Field{Window: wi, OriginalField: graph.Span{Start: originalOpen, Stop: originalEnd}, ProjectedField: graph.Span{Start: open, Stop: end}, OriginalTarget: graph.Span{Start: originalStart, Stop: originalStop}, ProjectedTarget: graph.Span{Start: start, Stop: stop}, Old: link.Target, New: replacement})
			count++
		}
		if count != owned[f.Tuple] {
			return "", nil, false
		}
	}
	if budget[f.Tuple] != f.Multiplicity || len(fields) != f.Multiplicity {
		return "", nil, false
	}
	return string(private), fields, true
}

type agreementMappedCodeP2Single struct {
	Body, HTML             string
	Field, DiagnosticIndex int
	Source                 agreementMappedCodeP2Reading
	Page                   agreementHTML
	Parts                  [][]agreementCodePart
	Diagnostics            []render.Diagnostic
	Failures               []agreementFailure
}

type agreementMappedCodeP2Declaration struct {
	Body, Private, Case, Selected, HTML, PrivateHTML string
	Source, PrivateSource                            agreementMappedCodeP2Reading
	Fields                                           []agreementMappedCodeP2Field
	Page, PrivatePage                                agreementHTML
	Parts, PrivateParts                              [][]agreementCodePart
	Diagnostics, PrivateDiagnostics                  []render.Diagnostic
	Before, After                                    []agreementFailure
	Singles                                          []agreementMappedCodeP2Single
}

func agreementMappedCodeP2SignedProjection(before, after []agreementFailure, selected *agreementFailure, target string, count int) bool {
	if selected == nil || count < 1 || count > selected.Multiplicity {
		return false
	}
	want := maps.Clone(agreementMixedCurrent(before))
	signature := agreementSignature(selected)
	if want[signature] != 1 {
		return false
	}
	delete(want, signature)
	remaining := *selected
	remaining.Multiplicity -= count
	if remaining.Multiplicity > 0 {
		want[agreementSignature(&remaining)]++
	}
	renamed := *selected
	renamed.Tuple.Target, renamed.Multiplicity = target, count
	want[agreementSignature(&renamed)]++
	return maps.Equal(want, agreementMixedCurrent(after))
}

func agreementMappedCodeP2CitationCounts(citations []agreementCitation) map[agreementCitation]int {
	r := make(map[agreementCitation]int)
	for _, citation := range citations {
		r[citation]++
	}
	return r
}

func agreementMappedCodeP2PublicProjection(source, private *agreementMappedCodeP2Reading, page, privatePage *agreementHTML, parts, privateParts [][]agreementCodePart, f *agreementFailure, count int) bool {
	if source == nil || private == nil || page == nil || privatePage == nil || f == nil || !source.Valid || !private.Valid || count < 1 || count > f.Multiplicity || !slices.Equal(source.NeutralPositions, private.NeutralPositions) || len(source.NeutralPage) != len(parts) || len(private.NeutralPage) != len(privateParts) {
		return false
	}
	oldBudget, privateBudget := make(map[agreementCitation]int), make(map[agreementCitation]int)
	for i, window := range source.NeutralPage {
		owned, valid := agreementMatchCodeWindow(window.Text, parts[i])
		if !valid {
			return false
		}
		for tuple, n := range owned {
			oldBudget[tuple] += n
		}
	}
	for i, window := range private.NeutralPage {
		owned, valid := agreementMatchCodeWindow(window.Text, privateParts[i])
		if !valid {
			return false
		}
		for tuple, n := range owned {
			privateBudget[tuple] += n
		}
	}
	if !maps.Equal(oldBudget, agreementMappedCodeP2CitationCounts(page.CodeCitations)) || !maps.Equal(privateBudget, agreementMappedCodeP2CitationCounts(privatePage.CodeCitations)) || oldBudget[f.Tuple] != f.Multiplicity || page.CitationsInCode != len(page.CodeCitations) || privatePage.CitationsInCode != len(privatePage.CodeCitations) {
		return false
	}
	newTuple := f.Tuple
	newTuple.Target = strings.Repeat("q", len(f.Tuple.Target))
	for _, pair := range [][2]map[agreementCitation]int{{oldBudget, privateBudget}, {agreementMappedCodeP2CitationCounts(page.Citations), agreementMappedCodeP2CitationCounts(privatePage.Citations)}} {
		want := maps.Clone(pair[0])
		if want[f.Tuple] < count || want[newTuple] != 0 {
			return false
		}
		want[f.Tuple] -= count
		if want[f.Tuple] == 0 {
			delete(want, f.Tuple)
		}
		want[newTuple] = count
		if !maps.Equal(want, pair[1]) {
			return false
		}
	}
	if !cmp.Equal(page.Blocks, privatePage.Blocks) || !cmp.Equal(page.Headings, privatePage.Headings) || !cmp.Equal(page.CalloutTitles, privatePage.CalloutTitles) || !cmp.Equal(page.Failures, privatePage.Failures) || page.CitationsInCode != privatePage.CitationsInCode || !cmp.Equal(source.Native, private.Native) || !cmp.Equal(source.Tree, private.Tree) || !cmp.Equal(source.Sites, private.Sites) || !cmp.Equal(source.HTMLSites, private.HTMLSites) {
		return false
	}
	oldTargets, privateTargets := make(map[string]int), make(map[string]int)
	for _, target := range source.Check.Targets {
		oldTargets[target]++
	}
	for _, target := range private.Check.Targets {
		privateTargets[target]++
	}
	if oldTargets[f.Tuple.Target]-privateTargets[f.Tuple.Target] != count || privateTargets[newTuple.Target]-oldTargets[newTuple.Target] != count || oldTargets[newTuple.Target] != 0 {
		return false
	}
	delete(oldTargets, f.Tuple.Target)
	delete(oldTargets, newTuple.Target)
	delete(privateTargets, f.Tuple.Target)
	delete(privateTargets, newTuple.Target)
	return maps.Equal(oldTargets, privateTargets)
}

func agreementMappedCodeP2Projection(r *agreementMappedCodeP2Declaration) bool {
	if r == nil || len(r.Fields) == 0 || len(r.Singles) != len(r.Fields) {
		return false
	}
	var selected *agreementFailure
	for i := range r.Before {
		if agreementSignature(&r.Before[i]) == r.Selected {
			if selected != nil {
				return false
			}
			selected = &r.Before[i]
		}
	}
	if selected == nil || len(r.Fields) != selected.Multiplicity || !agreementMappedCodeP2SignedProjection(r.Before, r.After, selected, strings.Repeat("q", len(selected.Tuple.Target)), len(r.Fields)) || !agreementMappedCodeP2PublicProjection(&r.Source, &r.PrivateSource, &r.Page, &r.PrivatePage, r.Parts, r.PrivateParts, selected, len(r.Fields)) {
		return false
	}
	whole := []byte(r.Body)
	expected := slices.Clone(r.Diagnostics)
	seen := make(map[int]bool)
	for i, field := range r.Fields {
		single := &r.Singles[i]
		span := field.OriginalTarget
		if single.Field != i || span.Start < 0 || span.Stop > len(r.Body) || span.Start >= span.Stop || r.Body[span.Start:span.Stop] != selected.Tuple.Target || field.Old != selected.Tuple.Target || field.New != strings.Repeat("q", len(field.Old)) || len(r.Diagnostics) != len(single.Diagnostics) || single.DiagnosticIndex < 0 || single.DiagnosticIndex >= len(r.Diagnostics) || seen[single.DiagnosticIndex] {
			return false
		}
		seen[single.DiagnosticIndex] = true
		one := []byte(r.Body)
		copy(one[span.Start:span.Stop], field.New)
		copy(whole[span.Start:span.Stop], field.New)
		if string(one) != single.Body || !agreementMappedCodeP2SignedProjection(r.Before, single.Failures, selected, field.New, 1) || !agreementMappedCodeP2PublicProjection(&r.Source, &single.Source, &r.Page, &single.Page, r.Parts, single.Parts, selected, 1) {
			return false
		}
		for di, old := range r.Diagnostics {
			changed := single.Diagnostics[di]
			if di != single.DiagnosticIndex {
				if !cmp.Equal(old, changed) {
					return false
				}
				continue
			}
			if old.Kind != render.DiagWikilinkBroken || old.Target != field.Old || changed.Target != field.New || old.Kind != changed.Kind || old.Section != changed.Section || old.Block != changed.Block || changed.Message != strings.ReplaceAll(old.Message, strconv.Quote(field.Old), strconv.Quote(field.New)) {
				return false
			}
			expected[di] = changed
		}
	}
	return string(whole) == r.Private && cmp.Equal(expected, r.PrivateDiagnostics)
}

func agreementMappedCodeP2Declare(t *testing.T, body, name, signature string) (agreementMappedCodeP2Declaration, bool) {
	t.Helper()
	r := agreementMappedCodeP2Declaration{Body: body, Case: name, Selected: signature, Source: agreementMappedCodeP2Read(body)}
	raw, page, before := agreementProseP1Failures(t, body)
	r.HTML, r.Page, r.Before, r.Diagnostics = raw.HTML, page, before, raw.Diagnostics
	var selected *agreementFailure
	for i := range before {
		if agreementSignature(&before[i]) == signature {
			if selected != nil {
				return r, false
			}
			selected = &before[i]
		}
	}
	var partsOK bool
	r.Parts, partsOK = agreementCodeWindowParts(raw.HTML)
	if !partsOK {
		return r, false
	}
	private, fields, owned := agreementMappedCodeP2Physical(body, selected, &r.Source, r.Parts)
	if !owned {
		return r, false
	}
	r.Private, r.Fields, r.PrivateSource = private, fields, agreementMappedCodeP2Read(private)
	pr, pp, after := agreementProseP1Failures(t, private)
	r.PrivateHTML, r.PrivatePage, r.After, r.PrivateDiagnostics = pr.HTML, pp, after, pr.Diagnostics
	r.PrivateParts, partsOK = agreementCodeWindowParts(pr.HTML)
	if !partsOK {
		return r, false
	}
	for i, field := range fields {
		one := []byte(body)
		copy(one[field.OriginalTarget.Start:field.OriginalTarget.Stop], field.New)
		single := agreementMappedCodeP2Single{Field: i, Body: string(one), DiagnosticIndex: -1, Source: agreementMappedCodeP2Read(string(one))}
		sr, sp, failures := agreementProseP1Failures(t, single.Body)
		single.HTML, single.Page, single.Diagnostics, single.Failures = sr.HTML, sp, sr.Diagnostics, failures
		single.Parts, partsOK = agreementCodeWindowParts(sr.HTML)
		if !partsOK || len(raw.Diagnostics) != len(sr.Diagnostics) {
			return r, false
		}
		count := 0
		for di := range raw.Diagnostics {
			if !cmp.Equal(raw.Diagnostics[di], sr.Diagnostics[di]) {
				single.DiagnosticIndex = di
				count++
			}
		}
		if count != 1 {
			return r, false
		}
		r.Singles = append(r.Singles, single)
	}
	projected := agreementMappedCodeP2Projection(&r)
	return r, projected
}

