func agreementMappedCodeP2Difference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	rows := agreementMappedCodeP2Declarations()
	for i := range rows {
		r := &rows[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if raw != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementMappedCodeP2Read(c.Body)
		private, fields, owned := agreementMappedCodeP2Physical(c.Body, f, &source, r.Parts)
		if !owned || private != r.Private || !cmp.Equal(fields, r.Fields) || !cmp.Equal(source, r.Source) || !cmp.Equal(agreementMappedCodeP2Read(private), r.PrivateSource) || !agreementMappedCodeP2Projection(r) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page"
	}
	return "", "", ""
}

func agreementMappedCodeP2Selected(t *testing.T, r *agreementMappedCodeP2Declaration) agreementFailure {
	t.Helper()
	var matches []agreementFailure
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			matches = append(matches, *f)
		}
	}
	if len(matches) != 1 {
		t.Fatal("caught: mapped code selected whole receipt is not unique")
	}
	return matches[0]
}

func agreementMappedCodeP2Clone(t *testing.T, r *agreementMappedCodeP2Declaration) agreementMappedCodeP2Declaration {
	t.Helper()
	b, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	var cloned agreementMappedCodeP2Declaration
	if err = json.Unmarshal(b, &cloned); err != nil {
		t.Fatal(err)
	}
	return cloned
}

func TestAgreementMappedCodeP2OwnedSource(t *testing.T) {
	t.Parallel()
	rows := agreementMappedCodeP2Declarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			pairs := []struct {
				Body   string
				Source agreementMappedCodeP2Reading
			}{{r.Body, r.Source}, {r.Private, r.PrivateSource}}
			for pi := range pairs {
				pair := &pairs[pi]
				if diff := cmp.Diff(pair.Source, agreementMappedCodeP2Read(pair.Body)); diff != "" {
					t.Fatalf("caught: complete mapped code original source and whole projected windows (-want +got):\n%s", diff)
				}
			}
			f := agreementMappedCodeP2Selected(t, r)
			private, fields, owned := agreementMappedCodeP2Physical(r.Body, &f, &r.Source, r.Parts)
			if !owned || private != r.Private || !cmp.Equal(fields, r.Fields) {
				t.Fatal("caught: mapped code every original field and private byte bound")
			}
			for si := range r.Singles {
				single := &r.Singles[si]
				if diff := cmp.Diff(single.Source, agreementMappedCodeP2Read(single.Body)); diff != "" {
					t.Fatalf("caught: complete mapped code single-field source (-want +got):\n%s", diff)
				}
			}
		})
	}
}

func TestAgreementMappedCodeP2OwnedPublic(t *testing.T) {
	t.Parallel()
	rows := agreementMappedCodeP2Declarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			records := []struct {
				Body, HTML  string
				Page        agreementHTML
				Parts       [][]agreementCodePart
				Diagnostics []render.Diagnostic
				Failures    []agreementFailure
			}{{r.Body, r.HTML, r.Page, r.Parts, r.Diagnostics, r.Before}, {r.Private, r.PrivateHTML, r.PrivatePage, r.PrivateParts, r.PrivateDiagnostics, r.After}}
			for ri := range records {
				record := &records[ri]
				raw, page, failures := agreementProseP1Failures(t, record.Body)
				parts, valid := agreementCodeWindowParts(raw.HTML)
				if !valid || raw.HTML != record.HTML || !cmp.Equal(page, record.Page) || !cmp.Equal(parts, record.Parts) || !cmp.Equal(raw.Diagnostics, record.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(record.Failures)) {
					t.Fatal("caught: complete mapped code public, diagnostic and signed ledgers")
				}
			}
			for si := range r.Singles {
				single := &r.Singles[si]
				raw, page, failures := agreementProseP1Failures(t, single.Body)
				parts, valid := agreementCodeWindowParts(raw.HTML)
				if !valid || raw.HTML != single.HTML || !cmp.Equal(page, single.Page) || !cmp.Equal(parts, single.Parts) || !cmp.Equal(raw.Diagnostics, single.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(single.Failures)) {
					t.Fatal("caught: complete mapped code single public and diagnostic ledgers")
				}
			}
			if !agreementMappedCodeP2Projection(r) {
				t.Fatal("caught: mapped code whole projection and every single diagnostic owner")
			}
			f := agreementMappedCodeP2Selected(t, r)
			kind, authority, wrong := agreementMappedCodeP2Difference(agreementCase{Body: r.Body}, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			if kind != "debt" || authority != "#1011 stage 5" || wrong != "page" {
				t.Fatal("caught: mapped code complete original receipt lacks page debt")
			}
		})
	}
}

func TestAgreementMappedCodeP2OwnedCensus(t *testing.T) {
	t.Parallel()
	prospects := agreementMappedCodeP2Prospects()
	if len(prospects) != 107 || len(agreementMappedCodeP2Declarations()) != 19 {
		t.Fatal("caught: whole mapped code declared prospect and control set")
	}
	for i, p := range prospects {
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			r, eligible := agreementMappedCodeP2Declare(t, p.Body, p.Case, p.Selected)
			if eligible != p.Eligible {
				t.Fatalf("caught: whole mapped code source eligibility and refusal set case=%s selected=%s got=%v want=%v", p.Case, p.Selected, eligible, p.Eligible)
			}
			f := agreementMappedCodeP2Selected(t, &r)
			kind, authority, wrong := agreementMappedCodeP2Difference(agreementCase{Body: p.Body}, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			if (kind != "") != p.Eligible || (p.Eligible && (kind != "debt" || authority != "#1011 stage 5" || wrong != "page")) {
				t.Fatal("caught: whole mapped code original classifier agrees with physical controls")
			}
		})
	}
}

func TestAgreementMappedCodeP2OwnedRefusals(t *testing.T) {
	t.Parallel()
	rows := agreementMappedCodeP2Declarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			f := agreementMappedCodeP2Selected(t, r)
			refuse := func(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) {
				t.Helper()
				if kind, _, _ := agreementMappedCodeP2Difference(c, f, raw, page, diagnostics, failures); kind != "" {
					t.Fatal("caught: mapped code refuses changed whole source or context")
				}
			}
			refuse(agreementCase{Body: r.Body}, nil, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(agreementCase{Body: r.Body}, &f, r.HTML, nil, r.Diagnostics, r.Before)
			refuse(agreementCase{Body: r.Body + "!"}, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(agreementCase{Body: r.Body, Title: "outside"}, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(agreementCase{Body: r.Body, Companions: capturedBodies{"outside.md": "outside"}}, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(agreementCase{Body: r.Body}, &f, r.HTML+"!", &r.Page, r.Diagnostics, r.Before)
			page := r.Page
			page.Headings = append(slices.Clone(page.Headings), "outside")
			refuse(agreementCase{Body: r.Body}, &f, r.HTML, &page, r.Diagnostics, r.Before)
			diagnostics := append(slices.Clone(r.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(agreementCase{Body: r.Body}, &f, r.HTML, &r.Page, diagnostics, r.Before)
			foreign := agreementFailure{Property: "P0", Identity: "outside", Tuple: agreementCitation{Target: "outside"}, Direction: "page-only", Multiplicity: 1}
			failures := append(slices.Clone(r.Before), foreign)
			refuse(agreementCase{Body: r.Body}, &f, r.HTML, &r.Page, r.Diagnostics, failures)
		})
	}
}

func TestAgreementMappedCodeP2OwnedPhysicalRefusals(t *testing.T) {
	t.Parallel()
	rows := agreementMappedCodeP2Declarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			f := agreementMappedCodeP2Selected(t, r)
			refuse := func(body string, f *agreementFailure, source *agreementMappedCodeP2Reading, parts [][]agreementCodePart) {
				t.Helper()
				if _, _, owned := agreementMappedCodeP2Physical(body, f, source, parts); owned {
					t.Fatal("caught: mapped code refuses another physical property or borrowed source window")
				}
			}
			refuse(r.Body, nil, &r.Source, r.Parts)
			refuse(r.Body, &f, nil, r.Parts)
			refuse(r.Body+"q", &f, &r.Source, r.Parts)
			for _, edit := range []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P0" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Cut = "outside" }} {
				changed := f
				edit(&changed)
				refuse(r.Body, &changed, &r.Source, r.Parts)
			}
			changed := agreementMappedCodeP2Clone(t, r)
			changed.Source.NeutralPositions = nil
			refuse(r.Body, &f, &changed.Source, r.Parts)
			changed = agreementMappedCodeP2Clone(t, r)
			span := changed.Fields[0].ProjectedField
			changed.Source.NeutralPositions[span.Start+1]++
			refuse(r.Body, &f, &changed.Source, r.Parts)
			changed = agreementMappedCodeP2Clone(t, r)
			changed.Source.NeutralPage[changed.Fields[0].Window].Span.Stop = len(changed.Source.Neutral) + 1
			refuse(r.Body, &f, &changed.Source, r.Parts)
		})
	}
}

func TestAgreementMappedCodeP2OwnedProjectionRefusals(t *testing.T) {
	t.Parallel()
	rows := agreementMappedCodeP2Declarations()
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			t.Parallel()
			refuse := func(r *agreementMappedCodeP2Declaration) {
				t.Helper()
				if agreementMappedCodeP2Projection(r) {
					t.Fatal("caught: mapped code refuses changed whole projection")
				}
			}
			for _, edit := range []func(*agreementMappedCodeP2Declaration){
				func(r *agreementMappedCodeP2Declaration) {
					r.Before = append(r.Before, agreementFailure{Property: "P0", Identity: "outside", Tuple: agreementCitation{Target: "outside"}, Multiplicity: 1})
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.After = append(r.After, agreementFailure{Property: "P3", Identity: "outside", Fragment: "outside", Cut: "outside", Multiplicity: 1})
				},
				func(r *agreementMappedCodeP2Declaration) { r.After = nil },
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivatePage.Headings = append(r.PrivatePage.Headings, "outside")
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivatePage.CodeCitations = append(r.PrivatePage.CodeCitations, agreementCitation{Target: "outside", State: "wikilink-broken"})
					r.PrivatePage.CitationsInCode++
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivateSource.Sites = append(r.PrivateSource.Sites, agreementNativeCodePayloadSite{Kind: "outside"})
				},
				func(r *agreementMappedCodeP2Declaration) { r.PrivateSource.NeutralPositions = nil },
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivateSource.Check.Targets = append(r.PrivateSource.Check.Targets, "outside")
				},
				func(r *agreementMappedCodeP2Declaration) { r.Singles[0].Field = -1 },
				func(r *agreementMappedCodeP2Declaration) { r.Singles[0].Body += "!" },
				func(r *agreementMappedCodeP2Declaration) { r.Singles[0].DiagnosticIndex = -1 },
				func(r *agreementMappedCodeP2Declaration) {
					r.Singles[0].Diagnostics[r.Singles[0].DiagnosticIndex].Message = "outside"
				},
				func(r *agreementMappedCodeP2Declaration) {
					r.PrivateDiagnostics = append(r.PrivateDiagnostics, render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
				},
				func(r *agreementMappedCodeP2Declaration) { r.Fields[0].OriginalTarget.Start-- },
			} {
				changed := agreementMappedCodeP2Clone(t, r)
				edit(&changed)
				refuse(&changed)
			}
			if len(r.Fields) > 1 {
				changed := agreementMappedCodeP2Clone(t, r)
				changed.Singles[1].DiagnosticIndex = changed.Singles[0].DiagnosticIndex
				refuse(&changed)
			}
		})
	}
}

func TestAgreementMappedCodeP2OwnedReaderRefusals(t *testing.T) {
	t.Parallel()
	if agreementMappedCodeP2Read(string([]byte{255})).Valid {
		t.Fatal("caught: mapped code source refuses invalid UTF8")
	}
}
